INSERT INTO `recipe` VALUES (1,'Aloo Keema','[\"Minced beef/lamb/chicken\", \"Potatoes\", \"Onion\", \"Tomatoes\", \"Green chilies\", \"Ginger garlic paste\", \"Turmeric\", \"Red chili powder\", \"Coriander powder\", \"Garam masala\", \"Oil\", \"Salt\"]','Sauté onions until golden. Add ginger-garlic paste and ground meat. Cook until browned, then add chopped potatoes and spices. Cover and simmer until potatoes are tender. Garnish and serve with roti or rice.','400 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747988934/kts4fp5jro8esgirvo37.jpg'),(2,'Bhindi Masala','[\"Okra (bhindi)\", \"Onions\", \"Tomatoes\", \"Green chilies\", \"Cumin seeds\", \"Turmeric\", \"Red chili powder\", \"Coriander powder\", \"Salt\", \"Oil\"]','Slice okra and sauté in oil until no longer slimy. In another pan, sauté onions, tomatoes, and spices. Add the cooked okra and mix well. Cook briefly and serve with chapati.','150 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747989962/z3tmye4rzp87o84apyxr.jpg'),(3,'Biryani','[\"Basmati rice\", \"Chicken\", \"Yogurt\", \"Onions\", \"Tomatoes\", \"Ginger-garlic paste\", \"Biryani masala\", \"Saffron\", \"Mint\", \"Coriander\", \"Oil\", \"Salt\"]','Marinate meat in yogurt and spices. Layer parboiled rice and cooked meat in a pot with saffron-infused milk. Cover and steam on low heat until fully cooked. Mix gently and serve with raita.','500 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747989974/f9sgc9wqaafstvd7zikv.jpg'),(4,'Brown Karahi','[\"Chicken or beef\", \"Tomatoes\", \"Onions\", \"Green chilies\", \"Yogurt\", \"Garlic\", \"Ginger\", \"Karahi masala\", \"Oil\", \"Salt\"]','Cook chicken in oil with browned onions, ginger, garlic, and tomatoes. Add spices and simmer until the oil separates and chicken is tender. Garnish with green chilies and coriander. Serve with roti or naan.','480 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990055/ajzecjzd2zgnvlvsa0qb.jpg'),(5,'Chana Chaat','[\"Boiled chickpeas\", \"Onions\", \"Tomatoes\", \"Green chilies\", \"Coriander\", \"Chaat masala\", \"Lemon juice\", \"Salt\"]','Mix boiled chickpeas with chopped onions, tomatoes, green chilies, coriander, and tamarind chutney. Season with chaat masala and lemon juice. Serve cold as a snack.','220 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990065/galtzwaetunslj3vrvht.jpg'),(6,'Chicken Handi','[\"Chicken\", \"Yogurt\", \"Cream\", \"Onions\", \"Tomatoes\", \"Ginger garlic paste\", \"Green chilies\", \"Spices\", \"Butter\", \"Salt\"]','Cook chicken in a clay pot (handi) with onions, tomatoes, yogurt, and spices. Simmer until thick and aromatic. Garnish with cream and coriander. Serve hot.','510 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990084/q60tzqwbagukgc0kkx4d.jpg'),(7,'Chicken Korma','[\"Chicken\", \"Yogurt\", \"Onions\", \"Ginger garlic paste\", \"Korma masala\", \"Cardamom\", \"Cinnamon\", \"Oil\", \"Salt\"]','Sauté onions, add ginger-garlic paste and chicken pieces. Add korma spices and yogurt. Cook covered until chicken is tender and oil separates. Garnish with nuts and coriander. Serve with naan.','480 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990097/z4zgyzxpxi8z3k9hlunw.jpg'),(8,'Daal Fry','[\"Split lentils\", \"Onions\", \"Tomatoes\", \"Garlic\", \"Cumin seeds\", \"Turmeric\", \"Red chili powder\", \"Coriander powder\", \"Salt\", \"Ghee\"]','Boil lentils until soft. In a pan, sauté cumin, onions, garlic, and tomatoes with spices. Add the cooked lentils and simmer for a few minutes. Garnish with coriander and serve with rice or roti.','280 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990107/tb9tkoart14oi2dnjjgy.jpg'),(9,'Haleem','[\"Wheat grains\", \"Split lentils\", \"Beef or chicken\", \"Onions\", \"Ginger-garlic paste\", \"Garam masala\", \"Coriander powder\", \"Ghee\", \"Salt\"]','Soak wheat and lentils overnight. Cook meat separately until tender. In a large pot, cook soaked grains with spices until soft, then add shredded meat. Blend the mixture slightly with a hand blender. Cook until thickened, then garnish with fried onions, ginger, coriander, and lemon. Serve hot.','450 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990117/uii4pzzyxmalgoz2vv48.jpg'),(10,'Nihari','[\"Beef shank or lamb\", \"Onions\", \"Ginger-garlic paste\", \"Nihari masala\", \"Flour\", \"Oil\", \"Salt\"]','Heat oil and sauté onions until golden. Add beef shanks and cook until browned. Stir in ginger-garlic paste, nihari masala, and yogurt. Add water and simmer on low heat for 6-8 hours. Before serving, add a flour slurry for thickening and simmer briefly. Garnish with fried onions, ginger, and coriander. Serve with naan.','550 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990139/xlegybvbcoggfran8hng.jpg'),(11,'Pulao','[\"Basmati rice\", \"Beef or chicken\", \"Yogurt\", \"Onions\", \"Whole spices\", \"Ginger-garlic paste\", \"Green chilies\", \"Salt\"]','Rinse basmati rice until the water runs clear and soak it for 30 minutes. In a pot, heat oil and add cumin seeds, letting them sizzle. Sauté chopped onions until golden, then add ginger-garlic paste and cook briefly. Stir in chopped tomatoes and cook until soft, followed by mixed vegetables like peas and carrots. Add the drained rice and gently stir to combine, then pour in water and season with salt. Bring to a boil, reduce the heat, cover, and cook until the rice is tender and the water has been absorbed. Fluff with a fork and serve warm.','420 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990157/ekrtyh3fq4jymnomrkda.jpg'),(12,'Ramen','[\"Ramen noodles\", \"Chicken or tofu\", \"Soy sauce\", \"Garlic\", \"Ginger\", \"Boiled egg\", \"Spring onions\", \"Carrot\", \"Miso paste\", \"Sesame oil\"]','Bring water to a boil in a large pot and stir in soy sauce, mentsuyu, oyster sauce, chicken stock, chicken oil, sesame oil, and grated garlic to create a rich broth. Let it simmer for a few minutes, then add ramen noodles and cook until tender. Divide the noodles and broth into bowls, then top with sliced boiled eggs, chopped green onions, and sesame seeds. Serve hot.','400 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990172/txjw2wbsd2thinjwbq4m.jpg'),(13,'Samosa','[\"All-purpose flour\", \"Boiled potatoes\", \"Green peas\", \"Cumin seeds\", \"Garam masala\", \"Green chilies\", \"Salt\", \"Oil\"]','Begin by making the dough with all-purpose flour, salt, and oil, gradually adding water until it forms a firm texture. Let the dough rest under a damp cloth for 30 minutes. For the filling, mash boiled potatoes and sauté them with cumin seeds, onions, ginger, garam masala, turmeric, red chili powder, salt, and boiled peas. Allow the filling to cool. Roll the dough into ovals and cut each in half. Form cones with each piece, fill with the potato mixture, and seal the edges with water. Deep fry the samosas in hot oil over medium heat until golden brown and crisp. Serve hot with chutney.','300 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990186/ihe3kpzkoca45mzjivqc.jpg'),(14,'Seekh Kebab','[\"Minced meat\", \"Onion\", \"Ginger-garlic paste\", \"Coriander\", \"Cumin\", \"Garam masala\", \"Green chilies\", \"Salt\"]','To make seekh kebabs, start by combining minced meat (beef or lamb) with finely chopped onion, fresh coriander, mint leaves, ginger-garlic paste, ground cumin, coriander, garam masala, red chili powder, and salt in a large bowl. Mix thoroughly until the spices are evenly distributed. Cover and refrigerate the mixture for at least an hour to let the flavors develop. Once marinated, shape the mixture around skewers to form long kebabs. Grill them on medium-high heat for 10 to 12 minutes, turning occasionally until cooked through and nicely charred. Serve hot with naan and green chutney.','320 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990200/ghqpi12opyr2otkmnhw5.jpg'),(15,'Sushi','[\"Sushi rice\", \"Nori sheets\", \"Fish\", \"Avocado\", \"Cucumber\", \"Rice vinegar\", \"Soy sauce\", \"Wasabi\", \"Salt\"]','Rinse sushi rice and cook with water until done. Mix rice vinegar, sugar, and salt and fold into the rice once it’s slightly cooled. Prepare fillings such as raw fish, cucumber, or avocado. Place a nori sheet on a bamboo mat, spread the rice evenly leaving an edge, and add fillings across the center. Roll tightly, slice with a wet knife, and serve with soy sauce, pickled ginger, and wasabi.','350 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990215/h4e2jx6upupjszrohj8r.jpg'),(16,'White Karahi','[\"Chicken\", \"Yogurt\", \"Cream\", \"Ginger\", \"Garlic\", \"Green chilies\", \"Black pepper\", \"Salt\"]','Heat oil in a wok and add chicken pieces, cooking until golden. Add ginger-garlic paste and chopped green chilies and cook until fragrant. Stir in ground black pepper, cumin, coriander, and salt. Lower the heat and add yogurt, stirring constantly to avoid curdling. Simmer until the sauce thickens and the oil separates. Garnish with fresh coriander and serve hot with naan or rice.','480 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990237/wrlg1zfwwmlqfz4maqvr.jpg'),(17,'Roasted Peppers, Spinach & Feta Pizza','[\"feta cheese\", \"flatout flatbread\", \"garlic\", \"orange pepper\", \"onion\", \"bell pepper\", \"spinach leaves\", \"tomato\"]','Roll out your pizza dough and lay it on a parchment-lined baking sheet. Spread tomato sauce over the base and layer it with fresh spinach leaves, sliced roasted red peppers, and crumbled feta cheese. Sprinkle mozzarella on top and drizzle with olive oil. Season with salt and pepper, then bake in a preheated oven at 220°C (430°F) for about 15 to 20 minutes, or until the crust is golden and the cheese is bubbling. Slice and serve hot.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990254/wvohayaxcxirpglqtc47.jpg'),(18,'Durian Panna Cotta','[\"durian puree\", \"gelatine powder\", \"milk\", \"sugar\", \"water\", \"whipping cream\"]','Heat cream, sugar, and pureed durian until warm. Stir in bloomed gelatin until dissolved. Pour into molds and chill until set. Serve cold with fruit or syrup.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990267/u1xxpk676gyrnorgiog0.jpg'),(19,'No Fuss Sunday Slow-Cooker Balsamic Pot Roast','[\"beef chuck roast\", \"onion\", \"beef broth\", \"balsamic vinegar\", \"tomato paste\", \"cooking tapioca\", \"garlic cloves-minced\", \"seasoning- or\", \"salt and pepper\"]','Place a beef roast in a slow cooker with carrots, potatoes, onions, balsamic vinegar, beef broth, garlic, and herbs. Cook on low for 8 hours or high for 4 hours until the meat is tender. Shred and serve with the cooked vegetables and juices.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990274/irose75bla8uvgjjuern.jpg'),(20,'Thai Street Vendor Salmon Skewers','[\"yu choy\", \"brown sugar\", \"chili sauce\", \"fish sauce\", \"ginger\", \"ground turmeric\", \"lime\", \"salmon fillet\"]','In a bowl, mix fish sauce, brown sugar, lime juice, chili flakes, and grated ginger. Marinate cubed salmon in the mixture for 30 minutes. Thread the salmon onto skewers and grill over medium heat for 2-3 minutes per side until cooked through and slightly charred. Serve hot with dipping sauce or wrapped in lettuce leaves.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990288/ptburyruvpvxl23vpce7.jpg'),(21,'Pasty','[\"- 2 cups all-purpose flour\", \"- 1/2 cup butter\", \"- 1/2 cup water\", \"- 1 tsp salt\", \"- 1/2 tsp ground cumin\", \"- 1/2 tsp chili powder\", \"- 1/2 tsp turmeric powder\", \"- 1/2 cup boiled potatoes, mashed\", \"- 1/4 cup peas\", \"- 1/4 cup carrots, chopped\", \"- 1/4 cup onions, chopped\", \"- 1/4 cup cilantro, chopped\"]','Make a dough with flour, butter, and a pinch of salt, and chill it. Prepare a filling with chopped meat, potatoes, onions, and seasoning. Roll out the dough into circles, place filling in the center, fold over, and crimp the edges. Brush with egg wash and bake at 200°C (390°F) for 45 minutes until golden. Serve warm.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990304/gxyh8atmu65g5zk5k7i2.jpg'),(22,'Crispy Chicken Burger','[\"chicken breasts\", \"brioche buns\", \"american cheese\", \"cole slaw\", \"butter\", \"vegetable oil\", \"buttermilk\", \"hot sauce\", \"paprika\", \"onion powder\", \"garlic powder\", \"kosher salt\", \"pepper\", \"flour\", \"paprika\", \"baking powder\", \"cayenne pepper\", \"oregano\"]','Marinate chicken breasts in buttermilk with spices. Coat in seasoned flour and deep fry until golden and crispy. Assemble burgers with buns, lettuce, tomato, mayonnaise, and fried chicken.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990318/whrpyo6shyooyllsyhhp.jpg'),(23,'Serbian Raznjici - Kebabs With Pork, Bacon, Onion and Sweet Pepper','[\"pork meat\", \"bell pepper\", \"bell pepper\", \"onion\", \"cured bacon\", \"ground pepper\", \"salt\", \"salad oil\"]','Marinate pork cubes with oil, garlic, salt, and pepper for a few hours. Thread pork onto skewers, alternating with slices of bacon, onion chunks, and sweet peppers. Grill over medium-high heat, turning occasionally, for 10–12 minutes until pork is cooked and slightly charred. Serve hot with bread or salad.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990349/hbo3dtl8ugkivgrxivsu.jpg'),(24,'Chapli Kebab','[\"- 1 pound ground beef\", \"- 1 onion, finely chopped\", \"- 2 green chilies, finely chopped\", \"- 1 tomato, finely chopped\", \"- 1/4 cup fresh coriander, chopped\", \"- 1 teaspoon cumin powder\", \"- 1 teaspoon coriander powder\", \"- 1 teaspoon red chili powder\", \"- 1/2 teaspoon turmeric powder\", \"- 1/2 teaspoon garam masala\", \"- Salt, to taste\", \"- 1 egg\", \"- 1/4 cup besan (chickpea flour)\", \"- Vegetable oil, for frying\"]','Mix minced meat with chopped onions, tomatoes, herbs, and spices. Shape into flat patties and shallow fry until crispy on the outside. Serve with naan and yogurt dip.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990356/hsi2rywaned7uhhgnqng.jpg'),(25,'Gulab Jamun','[\"- 1 cup milk powder\", \"- 1/4 cup all-purpose flour\", \"- 1/4 tsp baking soda\", \"- 2 tbsp ghee (clarified butter)\", \"- 1/2 cup milk\", \"- Oil for deep frying\", \"\", \"For the sugar syrup:\", \"- 1 cup sugar\", \"- 1 cup water\", \"- 1/4 tsp cardamom powder\", \"- Saffron strands (optional)\"]','Make dough using milk powder, flour, baking soda, and milk. Form small balls and deep fry on low heat until golden. Prepare a sugar syrup with water, sugar, and cardamom. Soak the fried balls in warm syrup for at least 1 hour before serving.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990365/vk61ymsfenfbko9zpdsn.jpg'),(26,'Kofta','[\"- 500g minced beef or lamb\", \"- 1 onion, finely chopped\", \"- 2 cloves of garlic, minced\", \"- 1 teaspoon ginger paste\", \"- 1 teaspoon cumin powder\", \"- 1 teaspoon coriander powder\", \"- 1 teaspoon red chili powder\", \"- 1/2 teaspoon turmeric powder\", \"- Salt to taste\", \"- 1/4 cup fresh coriander leaves, chopped\", \"- 1/4 cup fresh mint leaves, chopped\", \"- 2 tablespoons gram flour (besan)\"]','Mix ground meat with grated onions, garlic, spices, and herbs. Form into balls and fry until browned. Simmer the meatballs in a tomato-based gravy with yogurt and spices until cooked through. Garnish with coriander and serve with rice or bread.','420 kcal','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990380/zw3lvde7dqcuurql3otb.jpg'),(27,'Chicken Tikka','[\"- 500g boneless chicken, cut into cubes\", \"- 1 cup yogurt\", \"- 2 tbsp ginger-garlic paste\", \"- 1 tbsp red chili powder\", \"- 1 tsp turmeric powder\", \"- 1 tsp garam masala\", \"- 1 tbsp lemon juice\", \"- Salt to taste\", \"- 2 tbsp oil\"]','1. In a bowl, mix yogurt, ginger-garlic paste, red chili powder, turmeric powder, garam masala, lemon juice, and salt.\n2. Add the chicken cubes to the marinade and mix well until all the pieces are coated. Let it marinate for at least 2 hours or overnight for best results.\n3. Preheat the oven to 200°C (400°F).\n4. Thread the marinated chicken pieces onto skewers and place them on a baking tray lined with foil.\n5. Drizzle oil over the chicken and bake in the preheated oven for 20-25 minutes, or until the chicken is cooked through and slightly charred.\n6. Serve hot with naan bread, salad, and mint chutney.\n\nCalories: Approximately 350 kcal','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990389/ahucizsxzocspz2jrnok.jpg'),(28,'Pizza','[\"- 1 pre-made pizza crust\", \"- 1 cup of cooked chicken tikka, shredded\", \"- 1 cup of mozzarella cheese\", \"- 1/2 cup of sliced onions\", \"- 1/2 cup of chopped bell peppers\", \"- 1/4 cup of sliced tomatoes\", \"- 2 tbsp of green chutney (coriander-mint sauce)\", \"- 1 tsp of chaat masala (spice mix)\", \"- 1 tsp of red chili powder\"]','Prepare or roll out pizza dough on a floured surface and place on a baking sheet. Spread tomato sauce evenly, then layer with cheese and desired toppings such as pepperoni, mushrooms, or vegetables. Bake in a preheated oven at 220°C (430°F) for 15-20 minutes until crust is golden and cheese melted. Slice and serve hot.','Not specified','https://res.cloudinary.com/dkkocyj9d/image/upload/v1747990409/seboe1zbhgmi44drnpan.jpg'),(631783,'Honeyed Bacon\" Baklava','[\"1 package (16 ounce) walnuts (4 cups)\", \"1/2 cup sugar\", \"1 teaspoon ground cinnamon\", \"1 package (16 ounce) frozen phyllo, thawed\", \"1 cup butter, melted\", \"1 jar (12 ounce) honey\", \"1 package (16 ounce) of bacon, fried crisp\"]','In large bowl of food processor, add walnuts, bacon, sugar, and cinnamon. Pulse until walnuts and bacon are chopped; set aside. (Be sure to fry the bacon to a crispy stage. Then it will chop up finely and evenly.)\nCut phyllo into 13\" by 9\" rectangles. In greased 13\" by 9\" baking dish, place 1 phyllo sheet; brush with melted butter. Repeat with phyllo and butter to make 5 more layers, overlapping any small strips of phyllo to make rectangles, if necessary.\nOver phyllo in baking dish, sprinkle 1 cup walnut mixture.\nRepeat steps 2 and 3 to make 3 more layers (4 layers total). Place remaining phyllo on top of last walnut layer; brush with butter.\nWith sharp knife, cut just halfway through layers in triangle or diamond pattern.\nBake in 300 degree oven for 1 hour and 25 minutes or until top is golden brown.\nIn small saucepan over medium-low heat, heat honey until hot but not boiling. Evenly spoon hot honey over hot baklava.\nCool Baklava in dish on wire rack at least 1 hour; cover with foil and let stand at room temperature until serving.\nTo serve, finish cutting, with a sharp knife, through layers to make triangles or diamonds.','395.15','https://img.spoonacular.com/recipes/631783-556x370.jpg'),(633352,'Bacon Wrapped Tofu Tacos','[\"1 12 oz package firm tofu, drained\", \"1 package flour tortillas, taco or fajita size\", \"8 oz package cream cheese, softened\", \"3 fresh jalapeno peppers, de-seeded and diced small\", \"2 cups monterey jack cheese, shredded\", \"1 pound bacon, cooked\", \"1 cup chicken broth\", \"Olive oil, just have the bottle on hand\", \"1 teaspoon cumin\", \"1 teaspoon chili powder\", \"1 teaspoon paprika\", \"2 garlic cloves, minced\"]','In a small bowl combine the cumin, chili powder, paprika, 1 minced clove of garlic and 2 tbsp of olive oil.  Slice the tofu very thin, about 1/2 inch per slice, then rub each slice with the spice mixture.  Set aside.\nHeat about 1 tbsp olive oil over medium high heat in a large pan.  Add the tofu, a few slices at a time, watching carefully.  Flip after about 1-2 minutes.  Cook until done  I let mine cook about 2-3 minutes per side.   Half each piece, wrap with bacon, then set aside and cover with aluminum foil.\nDo NOT wash the pan out  now put it back on the stove, reduce heat to medium and add the remaining minced garlic clove, 1 tbsp olive oil and diced jalapeno.  Saute until the peppers are almost getting a little bit brown and everything is fragrant.   Add the cream cheese, 1/2 cup cheese and chicken broth.  Whisk and bring to a slight boil; reducing the heat if you have to, preventing it from scorching. Once its combined and a sauce consistency, salt and pepper to your taste and pour into a separate bowl; cover.\nBring the heat back up to medium-high, and add another tablespoon of olive oil to the pan.  When hot add one tortilla at a time, turning after about 15-20 seconds to the other side.  Your end result will be tortillas slightly brown around the edges and a little bubbly in the middle.\nSet aside and cover.\nTo serve, stuff a tortilla with bacon-wrapped tofu, and drizzle the jalapeno creme on top and some Monterey jack.','497.42','https://img.spoonacular.com/recipes/633352-556x370.jpg'),(633650,'Baked Indian Samosas','[\"2 packages puff pastry\", \"1 egg\", \"1 teaspoon water\", \"1 large russet potato\", \"Water\", \"Salt\", \"2 bay leaves\", \"1 1/2 teaspoons coriander seeds\", \"1/2 teaspoon black peppercorns\", \"1/2 teaspoon red chili flakes\", \"3 ounces boneless, skinless chicken breast\", \"1 mango, peeled, pitted and finely diced\", \"1/4 cup peas\", \"1/2 Juice of lime\", \"5 tablespoons chipotle sauce\", \"1/2 teaspoon cumin seeds\", \"3 tablespoons cilantro leaves, minced\", \"Salt and freshly ground black pepper\"]','Preheat the oven to 425 degrees F.\nIn a small saucepan, add the potato and enough cold water to cover. Add a generous pinch of salt and bring to a boil over medium heat, then reduce the heat and simmer until tender, 12 to 15 minutes.\nBring 4 cups water to a simmer and add a generous pinch of salt, bay leaves, 1 teaspoon coriander seeds, peppercorns, chili flakes, and chicken breast. Simmer until cooked through, 8 to 10 minutes.\nMash the potato and finely shred the chicken and put into a large bowl. Combine with peas, mango, lime juice, chipotle sauce, remaining coriander seeds, cumin, cilantro, and salt and pepper, to taste. Mixing with a spoon or your hands, until well incorporated. Taste for seasoning and adjust, if necessary.\nRoll the puff pastry out slightly, flattening the seams. Using a paring knife to trace a 7-inch ring mold or bowl, cut the dough into 8 (7-inch wide) rounds. Cut each into 2 semicircles.\nPut a tablespoon or so of the filling in the center of a semicircle. Have a small bowl of water handy. Dip your finger in the water and run it along the edges of the semicircle. Arrange the samosas so the flat side is facing away from you. Grab the left corner and fold it over the dough in a triangular motion, so that this corner lands on the bottom right side of the filling. Do the same with the other corner.\nSqueeze bottom shut, and fold over, sealing with water and then press with a fork.  Repeat with remaining dough and filling. Arrange the 8 samosas on a lightly greased baking sheet.\nIn a small bowl, whisk the egg and 1 teaspoon water with a fork until thoroughly combined. Brush the tops with the egg wash.\nBake for 15 minutes at 425 degrees F, then turn heat down to 375 degrees F and bake for 10 more minutes. You can flip them over just before you turn the heat down, if you like.\nServe with chutney','784.46','https://img.spoonacular.com/recipes/633650-556x370.jpg'),(633959,'Balti Chicken','[\"4 boned and skinned chicken breast halves cut in 1\\\" cubes\", \"2 cups long-grain white rice cooked\", \"fresh cilantro chopped\", \"1 green bell pepper chopped\", \"oil for cooking\", \"1 large onion chopped\", \"1 red bell pepper chopped\"]','In a large heavy skillet or wok, heat oil over medium high heat and cook chicken until pieces are no longer pink. Add the chopped bell peppers and onions to the pan and stir fry 3-5 minutes. Add the Balti sauce and simmerabout 5 minutes.Serve over cooked white rice, garnished with chopped fresh cilantro.NOTES : \"Balti- basically, a stir-fried curry- originated with a nomadic people inIndia. Now it\'s the most popular dish at hot Indian restaurants inEngland. \"Balti houses\" are more popular in England than in India, wherethe cuisine is so regional. It supposedly comes from the \'Baltistan\'region in northern India- it\'s now part of north Pakistan- where the peoplewere nomadic and carried minimal cooking equipment.\"Make it lowfat. We had this for dinner last night- it was very good and not as spicyas you might imagine. I froze the remaining Balti sauce, and next time,instead of using chicken, I will substitute garbanzo beans and/or potatoes.','519.89','https://img.spoonacular.com/recipes/633959-556x370.jpg'),(634496,'BBQ Mac and Cheese','[\"1 cup cottage cheese\", \"\\u00bd cup Parmesan cheese\", \"\\u00bd cup ketchup\", \"1 tsp. brown sugar\", \"\\u00bd jalape\\u00f1o\", \"\\u00bd cup Italian parsley\", \"1\\u00bc cup milk\", \"3 cloves garlic\", \"1 onion \\u2013 diced\", \"\\u00be tsp. ground cumin\", \"\\u00bd tsp. salt\", \"\\u00bd tsp. black pepper\", \"2-3 Tbs. butter\", \"1 cup cheddar cheese shredded or your favorite\", \"\\u00bc cup Italian style breadcrumbs or homemade breadcrumbs\", \"1 lb. of your favorite macaroni\"]','Prepare the macaroni as directed.\nCombine in a food processor the cottage cheese, milk, Parmesan cheese, ketchup, brown sugar, jalapeo, garlic, parsley and seasonings.\nHeat a frying pan with butter and saut the onions until softened and transparent.\nHeat another frying pan with a pat of butter; add the bread crumbs; toss and brown a bit.\nPreheat Oven 325 degrees:\nButter a baking dish.  Add the macaroni, the mixture from the food processor, the shredded cheese, the onions and toss.\nTop with the bread crumbs a few pats of butter and grated Parmesan cheese and a little shredded cheese.\nBake 25  30 minutes; until slightly golden.','812.67','https://img.spoonacular.com/recipes/634496-556x370.jpg'),(634660,'Beef Pot Pies with Irish Cheddar Crust','[\"8 T. unsalted butter, cut into 1/4 inch pieces\", \"8 oz. Irish cheddar, or sharp cheddar cheese, shredded\", \"2 1/2 c. all-purpose flour\", \"1 T. sugar\", \"1 t. salt\", \"1 t. dry mustard\", \"dash of cayenne pepper\", \"1/3 c. ice water, plus more if needed\", \"4 t. vegetable oil, divided\", \"1 1/2 lb. beef chuck meat, well-trimmed and cut into 1/2 inch pieces\", \"salt & pepper\", \"1 . onion, chopped fine\", \"2 carrots, peeled and chopped small\", \"1 large clove of garlic, minced\", \"1 t. minced fresh thyme\", \"1 t. minced fresh marjoram\", \"3 T. flour\", \"1 (15 oz.) can of low-sodium beef broth\", \"3/4 c. water\", \"1 1/2 t. Dijon mustard\", \"2 T. chopped fresh parsley\", \"1 egg, lightly beaten\"]','Make the pastry: Place the cut up butter pieces in the freezer for 15 minutes to chill. Meanwhile, in the work bowl of a food processor combine flour, sugar, dry mustard, salt and cayenne pepper. Pulse to combine. After the butter has chilled, scatter the pieces over the flour mixture (still in the food processor), along with the cheddar. Pulse about 10 times. Sprinkle half the ice water over the dough, pulse about 3 times, repeat with remaining water, pulsing 3 more times. Pinch the dough to check if it sticks together, if not add a tablespoon or two more ice water, until it comes together. Dump the mix in a large bowl and press it together to form the dough. Divide dough in half, shaping each into a 4-inch disk. Wrap each piece in plastic wrap and refrigerate at least an hour.\nBegin the filling: Pat the meat dry with paper towels and season with salt & pepper. Heat 2 t. oil in a large skillet over medium high heat until just smoking. Add the meat in a single layer and cook, without stirring, until the meat browns well on the underside, anywhere between 5-10 minutes (the meat will give off liquid, just let it evaporate - leave it alone!) Stir the meat and cook another couple minutes, until it looses the raw color. Remove to a plate and set aside.\nReduce heat to medium, add the remaining 2 t. oil and the onions and carrots. Saute until softened and starting to brown, stirring occasionally, around 5 minutes. Add the garlic, thyme and marjoram, cook until very fragrant, about a minute. Stir in flour, cook and stir about a minute. Slowly add in the beef broth and water, then the meat, along with any juices left on the plate. Bring to a simmer, then reduce the heat to low, to med-low. Cover and cook, (adjusting the heat as necessary to maintain a simmer) stirring occasionally until the meat is just becoming tender, around 45 minutes. Remove from heat, add in the Dijon and parsley. Adjust seasoning with salt & pepper. Set aside to cool.\nRolling out the crust, filling & baking the pot pies: Remove the dough from the refrigerator 10 minutes before rolling it out. Roll the dough out on a well-floured surface, large enough to cut out 3, 7-inch circles out of each half (save the scraps). Line each cup of a large-sized muffin tin with the dough. (It won\'t look very pretty, you just kind of have your way with it to get it pressed in there.) Refrigerate the filled tins as well as the dough scraps 15 minutes to firm back up.\nMeanwhile, preheat oven to 400 degrees. After 15 minutes and the filling has cooled down quite a bit. Divide the mixture evenly between crusts. Divide the remaining dough into 6 balls. Roll out each piece wide enough to cover the pot pies. Pinch the top and bottom crust edges together to seal, and finish the edges in whatever decorative way you like. Brush the tops with the beaten egg. Bake 35-40 minutes, rotating the pan after 20 minutes. Remove from oven & let sit 5 minutes before (carefully) removing the pot pies from the tin.','719.12','https://img.spoonacular.com/recipes/634660-556x370.'),(637374,'Ceviche Tostadas','[\"2 pounds very fresh white fish, such as tilapia or red snapper\", \"6 tomatoes, diced\", \"1/2 bunch of cilantro, finely chopped\", \"1/4 of an onion, chopped\", \"8 ounces juice of about limes, or about 6. lemon or lime juice\", \"3 serrano chiles, stemmed and chopped\", \"3 tablespoons olive oil\", \"salt to taste\", \"Tostadas or tortilla chips to serve as accompaniment\"]','First you need to cut the fish into small pieces, like a centimeter dice. Put it all in the bottom of a large bowl. Next squeeze the juice from the limes (or lemon). Pour the juice over the fish and stir well.  The juice should cover the fish, if it doesn\'t, then add more.\nNext add the tomato, onion, cilantro, serrano chiles, olive oil, and some salt to the bowl. Stir well. Your ceviche is now prepared, it just needs time to marinate. I recommend making it a day ahead of time, because I like the flavor of the end result better. If you must make and serve it on the same day, just be sure it is  refrigerated at least 4 hours before serving.\nTo serve the ceviche, place it in a serving bowl with tostadas or tortilla chips on the side. You can spoon the ceviche on the tostadas, or dip the chips if you prefer. If you want, wedges of avocado make a nice garnish. Your ceviche will be chilled, fresh, and delicious. You can enjoy it with a glass of white wine, but my personal faves would be a Cadillac margarita, or an icy cold beer. Buen Provecho!','374.28','https://img.spoonacular.com/recipes/637374-556x370.jpg'),(637391,'Chai Pani’s Malabar Chicken Curry','[\"2 pounds chicken breast, cut into bite-size pieces\", \"3 smalls dried red chiles (cayenne, bird)\", \"1 teaspoon chili powder\", \"1/2 cup chopped cilantro (leaves and/or stems)\", \"15 curry leaves, finely chopped\", \"1/2 teaspoon fenugreek seeds\", \"1 teaspoon ginger\", \"1/4 tsp. ground coriander\", \"2 tablespoons fresh lime juice\", \"1 teaspoon mustard seeds\", \"4 cups chopped red onion (2 large onions)\", \"1/2 teaspoon salt\", \"3 cups chopped tomatoes\", \"1 teaspoon turmeric\", \"1 cup unsweetened coconut milk\", \"1/2 cup vegetable oil+ 1 Tb\"]','Pour  cup oil in a large sauce pot over medium heat. When the oil is hot, add the mustard seeds, fenugreek seeds, curry leaves, and red chiles.Saut for 1-2 minutes, then add the ginger and onions. Reduce the heat to medium-low and allow the onions to brown until they are dark and soft enough the smash with a spatulaabout 25-30 minutes.Add the chili powder, coriander, turmeric, and cilantromix together.Raise the heat back to medium and add the tomatoes, salt, and lime juice. Simmer, stirring occasionally, until the tomatoes have disintegrated and the oil separates out15-20 minutes.Add  cup of water and 1 cup coconut milk. Bring to a boil, then turn down the heat.In a separate skillet, heat 1 Tb. of oil over high. Add the chicken to the skillet and brown on all sides, leaving the centers pink2-4 minutes.Add the chicken to the curry and simmer 5-7 minutes until the chicken has cooked through. Serve over basmati rice.','543.76','https://img.spoonacular.com/recipes/637391-556x370.jpg'),(638316,'Chicken Shawarma Bowl','[\"8 small carrots\", \"16 Cherry Tomatoes, halved\", \"1 TBSP Cumin\", \"2 TBSP Fresh Dill\", \"4 cloves garlic, minced\", \"1 TBSP Garlic Powder\", \"1/2 cup Greek Yogurt\", \"1 TBSP Ground Pepper\", \"1/2 cup Hummus\", \"Juice of 1/2 a lemon\", \"1 cup long grain rice\", \"2 cups Low Sodium Chicken Broth\", \"1/2 TBSP Olive Oil\", \"1 TBSP Olive Oil\", \"1/2 onion, minced\", \"1 TBSP Onion Powder\", \"1/2 cup Parsley, roughly chopped\", \"Pita Chips, Naan Bread or Pita Bread\", \"1 TBSP Salt\", \"3 boneless skinless chicken breasts\", \"2 TBSP Turmeric\", \"1 TSP Turmeric Powder\", \"1 TBSP Peppe\", \"1 TBSP Peppe\"]','1. Preheat oven to 400 degrees. Peel carrots. On a baking sheet toss carrots with olive oil. Add spices and toss. Place in oven and cook for 30 minutes, flipping at 15 minutes.2. Meanwhile slice chicken breasts into 1/2 inch bite sized pieces. On a separate baking sheet, place chicken. Squeeze juice over chicken. Add spices and toss until evenly distributed. Place chicken in oven and bake till chicken is cooked though, about 23 minutes. Once done, set aside and let rest.3. As the chicken and carrots are cooking, prepare rice. Add olive oil to a medium pot on medium high heat. Add onion and garlic, stirring so garlic does not burn, and cook about 2 minutes. Add spices and stir to distribute evenly. Add rice, chicken broth an lemon juice. Bring to a boil and then cover and reduce to a simmer till rice is thoroughly cooked through, about 20 minutes.4. Make Taziki: Stir together yogurt with dill, garlic powder and pepper. Place in refrigerator till ready to serve.5. Serve: Place rice on bottom, then chicken. Add dollops of hummus and taziki on top of chicken.Sprinkle parsley and tomatoes on top. Scoop up with pita chips, naan or pita bread.ENJOY!','654.05','https://img.spoonacular.com/recipes/638316-556x370.'),(638825,'CHOCOLATE BANANA MORNING BUZZ SMOOTHIE','[\"1 banana\", \"1/2 cup coffee (hot or cold)\", \"2 tbsp dark cocoa powder\", \"1 tsp cinnamon\", \"1 scoop protein powder (hemp, whey, casein, soy, or multi-source plant protein)\", \"1 cup milk or non-dairy beverage\"]','Mix all ingredients into a blender and enjoy!','403.65','https://img.spoonacular.com/recipes/638825-556x370.jpg'),(641755,'Durian Panna Cotta','[\"200g Durian puree (blend durian to smooth)\", \"15g Gelatine powder\", \"600ml Fresh milk\", \"150g sugar\", \"80ml water\", \"80g Whipping cream\"]','Add gelatine to water to soak for 5 minutes.Combine fresh milk, whipping cream and sugar in a pot, put under medium heat  and stir until sugar dissolved. Bring the liquid mixture to light boil.Then add in soaked gelatine into it and stir until gelatine dissolved.Lastly add durian puree and mix well, do not boil but keep stirring it for 5-8 minutes at low heat. Strain and pour mixture in cups or moulds.Refrigerate for at least 2 hours and serve.','156.5','https://img.spoonacular.com/recipes/641755-556x370.jpg'),(642540,'Falafel Burgers','[\"2 cans garbanzo beans (chickpeas), drained and rinsed\", \"1 tablespoon chili powder\", \"1 tablespoon coriander\", \"1 tablespoon cumin\", \"4 tablespoons flour\", \"1 large handful parsley, chopped\", \"2 cloves garlic, grated or finely chopped\", \"2 Zest and juice of lemons\", \"4 pita pockets\", \"1 small red onion, chopped\", \"Salt and pepper, to taste\", \"1/2 cup tahini\", \"1 1/2 teaspoons turmeric\", \"1/4 cup vegetable oil\", \"3 tablespoons water\"]','Combine the chickpeas, onion, garlic, parsley, flour, spices, and salt, and pulse until the mixture is well combined. Form the mixture into 4 large patties.Heat the oil in a large, nonstick skillet set over medium-high heat. Cook for about 3 minutes per side.Make the tahini sauce: Whisk the tahini paste with the water, lemon juice and zest, salt, and freshly ground black pepper in a mixing bowl.Serve the burgers in pita pockets or on a bun. Top them with tahini sauce, lettuce, and tomato.','709.5','https://img.spoonacular.com/recipes/642540-556x370.jpg'),(642583,'Farfalle with Peas, Ham and Cream','[\"1 teaspoon butter\", \"3-4 slices of ham, diced\", \"Farfalle Pasta, or any shape pasta desired\", \"\\u00bd cup heavy cream ( milk can be a substitute)\", \"\\u00bd cup parmesan cheese\", \"1 cup frozen peas\", \"Salt and pepper\"]','Cook pasta according to package directions.In a skillet add the peas, butter, ham. Sautee for 5 minutes. Add the cream, salt and pepper and cook under medium heat for 5 to 10 minutes, or until the cream is slightly becoming thick. Remove from heat. When the pasta is cooked and drained, return to pan and add the sauce. Stir well and add the cheese.Serve nice and hot.','397.04','https://img.spoonacular.com/recipes/642583-556x370.jpg'),(643823,'Fried Udon With Dried Shrimp','[\"2 tablespoons oil\", \"1 tablespoon chopped garlic\", \"3 tablespoons dried shrimp (soaked and chopped)\", \"2 tablespoons chopped preserved radish (soaked 20 minutes and drained)\", \"1/2 tablespoon ground black pepper\", \"100 grams minced meat\", \"2 packets Udon noodles\", \"Coriander/parsley/chili to garnish\", \"1 tablespoon oyster sauce\", \"1/2 tablespoon light soya sauce\", \"1/2 teaspoon salt\", \"150 water\"]','Soak dried shrimp in warm water. Stir-fry vegetables and soaked shrimp in oil. Add cooked udon noodles and season with soy sauce, oyster sauce, and sesame oil. Toss well and serve hot.','233.71','https://img.spoonacular.com/recipes/643823-556x370.jpg'),(648475,'Japanese Gyoza Pot Stickers','[\"1/4 teaspoon Black pepper\", \"1 1/2 cups Cabbage\", \"Chili sesame oil, which is very very hot\", \"3 Dried mushrooms soaked in warm 2 teaspoons Ginger root grated\", \"3 To 4 green onions chopped\", \"3/4 pound ground beef (or pork)\", \"Salad oil\", \"1 tablespoon sesame oil\", \"1 tablespoon Kikkoman soy sauce\", \"Kkikkoman soy sauce\", \"1 tablespoon Cooking wine\", \"Gyoza wrappers\"]','Chop cabbage fine, place in colander and pour boiling water over the cabbage. Cool to touch, then squeeze cabbage well to get the water out. In a bowl mix cabbage, chopped green onions, chopped mushrooms and grated ginger. Mix ground beef, wine, soy sauce, sesame oil and black pepper together with vegetables; mix well. Place a small amount of filling (about 1 teaspoon) in center of gyoza wrapping and fold in half. Pleat edge to seal. If edges won\'t stick together, dampen the inside edge with a little water, then pleat. Put 2 tablespoon salad oil in Then, at edge of pan, pour in a little water, up to 1/4 of the depth of the pot-stickers. Cover, turn heat to low and simmer until water is gone. Serve with dipping sauce as appetizer, or with hot rice as entree.^^^^^^^^^^^^^^^^^^^^^^^^ ^ no way Jose!SAUCE:Mix soy sauce with chili sesame oil. Use a proportion of 10 parts soy sauce to 1 part oil; if you use a 5 to 1 proportion it may be a little hot for most people. The authentic sauce is a 2 to 1 proportion.','449.89','https://img.spoonacular.com/recipes/648475-556x370.jpg'),(648771,'Kashmiri Chicken','[\"Toasted Flaked Almonds\", \"4 Chicken Drumsticks, Skinned\", \"4 tablespoons Chicken Stock\", \"4 Chicken Thighs, Skinned\", \"teaspoon Chilli Paste\", \"4 tablespoons Tikka Curry Paste\", \"Flat-Leaf Parsley\", \"1 teaspoon Chopped Fresh Ginger\", \"Garlic crushed 1 teaspoon\", \"2 tablespoons Ground Almonds\", \"1 teaspoon Ground Cumin\", \"5 ounces Natural Yogurt\", \"Onion chopped 2\", \"Pickles\", \"Cooked Pilau Rice\", \"2 1/2 teaspoons salt\", \"2 tablespoons Sunflower Oil\", \"Poppadoms\", \"Poppadoms\"]','Slash chicken at intervals and place in a bowl. Mix together yogurt and curry paste, then stir into chicken, coating evenly. Cover and Chill for 1 hour.Heat oil in a large pan and fry onion and garlic for 4 to 5 minutes. Stir in cumin, ginger and chilli and cook gently for 1 minute. Add chicken and fry gently, turning occasionally, for about 10 minutes.Stir in any remaining marinade with stock and ground almonds. Cover and simmer for 15 minutes, or until chicken is cooked through. Add salt to taste.Scatter flaked almonds over chicken and garnish with flat-leaf parsley.Serve chicken with pilau rice, pickles and poppadoms.','289.1','https://img.spoonacular.com/recipes/648771-556x370.jpg'),(648910,'Kimchi','[\"6 pounds Napa cabbage\", \"3 tablespoons salt\", \"2 cups sliced scallions\", \"3 minced garlic cloves\", \"1 tablespoon ginger root minced or 2 tsp. ginger powder\", \"4 tablespoons dried ground chili pepper\", \"2 tablespoons sugar\"]','Shred cabbage in 2 inch strips. Mix with half the salt. Let stand 30 minutes. Wash and drain.   \nMix the scallions, garlic, ginger, chili pepper, cabbage and the rest of salt. Pack into a crock or glass jar.\nPut the containers aside for three or four days in a cool location. After that, store it in the refrigerator.','118.71','https://img.spoonacular.com/recipes/648910-556x370.jpg'),(649225,'Lamb Moussaka','[\"1/2 cup all purpose flour\", \"1 can diced tomatoes, undrained\", \"cup margarine\", \"1/2 cup dry red wine, optional\", \"4 egg, beaten\", \"2 1/2 pounds eggplant, (3 large)\", \"4 cups Natrel Lactose Free Milk\", \"3 cups lactose free mozzarella cheese, shredded\", \"1/2 cup chopped fresh parsley\", \"2 clv garlic, chopped\", \"2 pounds ground lamb\", \"White Sauce\", \"Meat Sauce\", \"1/4 cup olive oil\", \"2 mediums Onion, chopped\", \"1 tablespoon dried oregano leaves\", \"1 tablespoon salt\", \"1 teaspoon salt\", \"1 salt and pepper, to taste\", \"1 can Tomato paste\", \"3 zucchini, sliced, 1/4 inch thick\"]','CUT eggplant into 1/4\" (5mm) thick slices. Layer in colander, sprinkling each layer with salt. Let stand 30 minutes.RINSE eggplant; pat dry. Place in single layer on baking sheet. Brush with olive oil. Broil, turning once for 4 to 6 minutes on each side, until golden and softened. Set aside. Repeat until all eggplants are cooked.SAUTE zucchini in large oiled frying pan until tender-crisp. Set aside.Meat Sauce:COOK lamb in large saucepan on high heat, breaking up with spoon, for 5 minutes. Drain off fat. Add onions, garlic and oregano. Cook on medium for 5 minutes. Add tomatoes, tomato paste and wine. Simmer 10 minutes, or until mixture starts to thicken. Stir in parsley, salt and pepper. Set aside.White Sauce:MELT margarine in large saucepan. Add flour, mixing until smooth. Gradually add milk. Cook, stirring constantly until mixture comes to a boil and is thickened. Add salt and nutmeg. Add a bit of hot mixture to beaten eggs then return to saucepan and cook 2 minutes longer, stirring occasionally.To Assemble:Tips:Place pan on a baking sheet or piece of foil to catch any drips that may boil over.MAKE-AHEAD: After assembling, cool completely, uncovered in refrigerator. Cover with plastic wrap and refrigerate for 1 day or overwrap with heavy foil and freeze up to 3 weeks. Thaw in refrigerator 48 hours before baking.Replace lamb with beef.A thin bottom layer of sauteed sliced potatoes can be added.A make-ahead layered Greek casserole that\'s ideal for potlucks and family reunions.','827.63','https://img.spoonacular.com/recipes/649225-556x370.jpg'),(649411,'Lebanese Tabouleh','[\"3 tablespoons cooked bulgur wheat\", \"3 cups flat leaf parsley, about one bushel\", \"1 tablespoon fresh mint\", \"3 tablespoons green onions, finely chopped\", \"1 Juice from lemon\", \"2 tablespoons olive oil\", \"1/4 cup roma tomatoes, finely chopped\"]','Remove stems from parsley and mint. Rinse leaves in a colander. Pat dry with paper towel.In a food processor pulse parsley and mint until finely chopped. Transfer to a large mixing bowl.Add green onions, tomatoes and bulgur wheat; stir to combine.Toss with lemon juice and olive oil. Refrigerate for an hour before serving.Serve on its own or with pita breadServes 2','212.51','https://img.spoonacular.com/recipes/649411-556x370.jpg'),(652598,'Murg Malai Tikka','[\"1 pound boneless chicken breast, cubed\", \"Sliced onions, tomatoes, lemon wedges, cilantro for garnish\", \"Ghee/butter/oil for brushing\", \"1 tablespoon fresh lemon juice\", \"3 tablespoons heavy cream\", \"1 tablespoon sour cream (optional)\", \"1 tablespoon grated mozzarella cheese\", \"1 tablespoon garlic paste\", \"1 tablespoon ginger paste\", \"2 tablespoons melted ghee [clarified butter]\", \"1 teaspoon dry cumin powder\", \"1 teaspoon dry coriander powder\", \"1 tablespoon red chilli powder\", \"1 1/2 tablespoons black pepper powder [adjust to taste]\", \"1/2 teaspoon cinnamon powder\", \"4 saffron strands [optional]\", \"2 teaspoons kasuri methi [dried fenugreek leaves, available in Indian grocery stores]\", \"3 drops orange food color [optional]\", \"kosher salt to taste\"]','Wash the chicken cubes thoroughly & pat dry with a paper towel.\nSoak the bamboo skewers in water for at least 1 hour.\nApply a mixture of one tablespoon lemon juice and salt over the chicken cubes and set aside for half an hour in a refrigerator.\nIn a bowl combine rest of the marinade ingredients and mix well to remove any lumps.\nRub this marinade on the chicken cubes .Transfer  the chicken pieces and marinade in a bowl ,cover the bowl with a plastic wrap and marinate overnight for at least 1-2 hours in a refrigerator.\nYou can use any one of the following for cooking the chicken :\nThis is what I do: Preheat the oven at 450 F broiler mode.Line a baking sheet with aluminum foil and arrange the chicken skewers on it.Brush the chicken pieces with ghee. Tip the sheet inside the oven on top rack and cook for about 22-25 minutes flipping it after 15 minutes till chicken is done on all sided but still tender.You may get some burnt marks on the chicken but thats okay!\nGrill the chicken for 2o minutes or till done and but still tender.In between keep on brushing with the ghee and the marinade\nHeat a large pan/skillet and coat it with ghee. Place the skewers with chicken piece  on the pan and cook medium heat for about 15-20 minutes turning them around and brushing with ghee and the marinade.Cook them till the chicken pieces are tender and you see brown colored spots on the tikkas.\nNotes:\nThe more the chicken marinates, the more the flavor.So, marinate the chicken for as long as you can.\nLeftover chicken tikkas can be stuffed into a tortilla or paratha and made into a kathi roll.\nBest served warm with tandoori naan.Even paneer [indian cottage cheese]or fish can also be made the same way.\nI refrain from using artificial food coloring though I have noted down in the recipe..go ahead and add it to the marinade if you wish.\nMake sure you season the marinade well, else the tikka will be tasteless.\nYou can use iron skewers too in place of bamboo ones.No need to soak them.\nEnjoy!','375.92','https://img.spoonacular.com/recipes/652598-556x370.jpg'),(653200,'No-bake Toasted Coconut Chocolate Cake with Chocolate Macaroon Cookies','[\"4 medium avocados\", \"1 cup dark cocoa or carob powder\", \"4 tbsp chocolate chips, melted\", \"1/2 cup toasted coconut\", \"1/2 cup coconut oil\", \"2/3 cup dates\", \"1/2 cup maple syrup\", \"2 tbsp almond or peanut butter\", \"1 1/2 cup pecans (or nut)\", \"1/2 C unsweetened coconut\", \"1 vanilla bean or 1 tsp vanilla extract\"]','In a mixing bowl, combine crushed chocolate macaroon cookies and toasted coconut. Add melted butter and press into a cake pan. Pour a ganache of melted chocolate and cream over the base. Chill in the fridge until set. Slice and serve.','434.99','https://img.spoonacular.com/recipes/653200-556x370.jpg'),(653304,'Not Momofuku Ginger Scallion Noodles','[\"2 teaspoons fish sauce\", \"1 tablespoon chopped garlic\", \"2 tablespoons of ginger finely minced\", \"1 cup grapeseed oil\", \"1 bunch large of green onions, sliced\", \"1 tablespoon honey\", \"kosher, sea or Himalayan salt to taste\", \"1 crushed red chile pepper\", \"1 teaspoon rice wine vinegar\", \"1 tablespoon toasted sesame seed oil\", \"1 tablespoon chopped shallots\", \"3/4 pound soba noodles\", \"2 teaspoons soy or wheat free tamari sauce\"]','Heat up the grapeseed oil in a saucepan over high heat until the oil is shimmery and hot, but not smoking.Add the green onions, ginger, garlic and shallots at once, but be careful, the oil will bubble and splatter. The onions will sizzle and wilt almost immediately and turn a bright green.Take the pan off the heat and stir the sauce with a wooden spoon. Add the fish sauce, sesame seed oil, rice wine vinegar, soy sauce, honey, crushed red chile pepper and salt to taste.Let sit for 15 minutes, then toss with your favorite noodles.  I used fresh Chinese egg noodles.','446.09','https://img.spoonacular.com/recipes/653304-556x370.jpg'),(653951,'Orange Scented Onigiri','[\"1 cup Uncooked Rice\", \"4 cloves\", \"3 Green Cardamom Pods\", \"2 centimeters Long Cinnamon Stick\", \"2 cloves Garlic\", \"2 Shallots, thinly sliced\", \"1/2 tablespoon Olive Oil\", \"1/2 Rind of Mandarin Orange, thinly shred\", \"1 teaspoon Chicken Stock Powder\", \"100 milliliters Fresh Mandarin Orange Juice\", \"1 cup Water\", \"1 1/2 tablespoons Golden Raisin\", \"1 1/2 tablespoons Almond Flakes, lightly toasted\", \"1/2 tablespoon Sliced Spring Onion, optional\"]','Cook Japanese short-grain rice until sticky. Once cooled slightly, mix in a hint of orange zest. Shape the rice into triangles using wet hands. Optionally, fill with salmon or umeboshi. Wrap a strip of nori around the base and serve.','524.16','https://img.spoonacular.com/recipes/653951-556x370.jpg'),(654072,'Oriental Filet Mignon on Crisp Kataifi with Shrimp Tempura','[\"2 filet mignon steaks, about 1 \\\" thick\", \"1/2 cup dry red wine\", \"2 tbsp. each: Light soy sauce, Raw Honey, Hoisin Sauce\", \"1 tsp. finely chopped fresh ginger\", \"1 tsp. minced garlic\", \"1 tsp. hot pepper flakes (optional)\", \"1 tbsp. rice vinegar\", \"4 sweet water shrimp with tails on (available at most Asian markets)\", \"2 egg whites, whisked\", \"2-3 tbsp. corn starch\", \"1 cup panko (Oriental bread bread crumbs)\", \"4-5 oz. Kataifi pastry (shredded phyllo)\", \"Oil for frying, brushing and grilling (a neutral oil such as Safflower is best)\"]','Combine the first three ingredients in a shallow dish and add the filet mignon steaks. Spoon the marinade over them until they are well covered, set aside for about 30 minutes, covered with plastic wrap.\nHeat oven to 400o.\nLine a baking sheet with parchment, and divide the kataifi into two neat rounds. Drizzle lightly with a neutral oil, and bake until golden and crisp. Remove from oven and set aside.\nMeanwhile, place the corn starch, whisked egg whites and panko in separate bowls.\nRoll each shrimp first in the corn starch, then in the egg whites and the in the panko. Pat them firmly with your palms to make sure the panko sticks well. Set aside on paper towels on a plate or tray. Repeat with the rest of the shrimp.\nFill a large deep skillet with oil (such as Safflower or Canola), enough to cover the shrimp when frying.\nTurn BBQ to high. Meanwhile, heat oil in frying pan until very hot, and fry the shrimp, turning once or twice, for about 2 minutes until golden. Place back on paper towels and set aside in a lightly warmed oven.\nWhen BBQ is very hot, remove steaks from marinade and grill on high for about 3-4 minutes on each side. While the steaks are grilling, add the rice vinegar, garlic, pepper flakes and ginger to the remaining marinade, and warm it up in a small saucepan until boiling, then set aside.\nTo serve: On each dinner plate place one mound of kataifi, topped by sliced filet mignon, drizzle with 2 spoonfuls of marinade and top with 2 fried shrimp. Serve with your favorite steamed vegetable(s) or stir fry.','662.37','https://img.spoonacular.com/recipes/654072-556x370.jpg'),(654313,'Pachai Payaru Kulambu (Green Moong Dal Curry)','[\"1 cup of pachai payaru/green moong dal - soaked for 3 hours and drain off water.\", \"5 garlic - remove skin\", \"5 shallots - remove skin\", \"1/2 inch ginger - sliced\", \"1 tsp turmeric powder\", \"1 tomato - sliced thinly\", \"1 tbsp plain curry powder\", \"1/2 cup coconut milk/cream\", \"Salt for taste\", \"1 1/2 tbsp ghee/butter/oil\", \"1 tsp cumin seeds\", \"2-3 dried red chilies - snipped to tiny pieces\", \"2-3 sprigs curry leaves\"]','Add dal, garlic, shallots, ginger, turmeric powder and 1/2 liter of water into a pot.\nSimmer till dal is half cooked.\nAdd tomato, curry powder and season with salt.\nContinue to simmer to soften dal.\nPour coconut milk, stir and remove from heat.\nTemper cumin, dried chilies and curry leaves in ghee.\nPour over dal and stir.','337.85','https://img.spoonacular.com/recipes/654313-556x370.jpg'),(654361,'Pakistani Rice','[\"1/2 large Onion\", \"3 tablespoons Butter\", \"cup Raisins\", \"1/2 cup Peas\", \"2 cups Precooked rice\", \"2 cups Water\", \"1 teaspoon Salt\"]','Place onion in 2 cups water. Boil 10-20 minutes. Remove onion from water.\nAdd raisins to butter and heat. Add rice to hot butter and raisins. Stir mixture constantly until rice is browned. Add peas (if frozen, thaw first).\nAdd the water minus onion. Bring to boil. Simmer 5 minutes in covered pan.\nIf any liquid remains, simmer uncovered until liquid is gone.','542.39','https://img.spoonacular.com/recipes/654361-556x370.jpg'),(654371,'Palak Gosht','[\"2Fry onion in oil till golden brown.\", \"Green chillies chopped 6 nos\", \"Fresh coriander leaves, chopped medium bunch\", \"Garlic chopped 1 medium pod\", \"Ginger crushed long 2 inch piece\", \"4Then add water i(1-2cup) and cook on medium flame till meat is tender.\", \"3Add meat and fry for 2-3 minutes, then add tomatoes, garlic, ginger and spices and fry for 5-7 minutes.\", \"Oil for frying\", \"Onion chopped 3 nos\", \"7Serve with roti or boiled rice.\", \"6Delicious Palak gosht is ready\", \"Spices: Salt to taste, Paprika to taste, Cutter\", \"Tomatoes chopped 3 nos\", \"1Boil palak in water , sieve and keep aside.\", \"Mutton 1 kilogram\", \"5Now add boiled palak and cook for 5 minutes then add fresh coriander and green chillies and simmer till oil separates out.\", \"Palak prepared, chopped 1/2 kilogram\", \"Mutton 1 kilogram\", \"5Now add boiled palak and cook for 5 minutes then add fresh coriander and green chillies and simmer till oil separates out.\", \"Palak prepared, chopped 1/2 kilogram\"]','Boil palak in water , sieve and keep aside.Fry onion in oil till golden brown.Add meat and fry for 2-3 minutes, then add tomatoes, garlic, ginger and spices and fry for 5-7 minutes.Then add water i(1-2cup) and cook on medium flame till meat is tender.Now add boiled palak and cook for 5 minutes then add fresh coriander and green chillies and simmer till oil separates out.Delicious Palak gosht is readyServe with roti or boiled rice.','583.48','https://img.spoonacular.com/recipes/654371-556x370.jpg'),(655316,'Peanut Butter Hummus','[\"1 can (19 oz/540 mL) chickpeas, drained and rinsed\", \"\\u00bd tsp (2 mL) ground cumin\", \"\\u00bc cup (60 mL) lemon juice\", \"1/2 cup peanut butter\", \"1/2 teaspoon salt\", \"\\u00bc cup (60 mL) hot water\"]','Place all ingredients in a food processor or blender. Whirl until smooth. Serve with veggies and crackers.Tip: If a thinner hummus is preferred, add additional water or lemon juice to taste.','148.74','https://img.spoonacular.com/recipes/655316-556x370.jpg'),(657747,'Rainbow trout with basil pea puree','[\"1 large filet of rainbow trout\", \"1/2 Zest of a lime\", \"Sprinkle of cayenne pepper\", \"Salt and pepper to taste\", \"3 cups frozen peas\", \"Handful of fresh basil leaves\", \"1 clove of garlic\", \"1/2 Juice of a lime\"]','Heat some olive oil in a pan.\nWith kitchen towels dab the filet to make sure it is dry. Sprinkle the filet on both sides with the salt, pepper and cayenne.\nPlace the filet skin side down in the pan. Sprinkle the zest on the flesh. Cook until the skin is golden and crisp, about three minutes. Then  flip over and continue to cook for another three to five minutes, depending on the level on doneness you prefer.\nWhile the fish is cooking, blend all the ingredients for the puree together. I tasted it and then found I would like some more basil so I added more in. Add the lime juice last.\nServe the trout with the puree and some more lime wedges on the side. Enjoy!','192.49','https://img.spoonacular.com/recipes/657747-556x370.jpg'),(659237,'San Francisco Cioppino','[\"2 pounds fresh tomatoes, peeled, seeded, and chopped (or 1 28-ounce can of tomatoes)\", \"24 clams, well scrubbed\", \"3 cups dry white wine\", \"4 pounds freshly cooked Dungeness crabs (approximately 2 lbs each)\", \"2 pounds fresh white fish, cut into large pieces\", \"1 tablespoon fresh basil, finely chopped\", \"Chopped fresh parsley\", \"3 large cloves garlic, minced\", \"1 teaspoon fresh ground black pepper\", \"1/4 cup olive oil\", \"1 teaspoon fresh oregano, chopped\", \"3/4 pound raw shrimp, peeled and deveined\", \"3/4 pound scallops\", \"3 ounces tomato paste\", \"1 medium yellow onion, finely chopped\"]','Remove the legs and claws from the crabs and break the body in half, reserving as much of the \"crab butter\" as possible (the yellow-colored center).Set crab pieces aside and force the crab butter through a sieve into a small bowl. Set aside.Place the clams in a pan, add 1 cup of wine, and steam, covered, over medium heat for 5 minutes or until clams open.Remove clams and discard any that do not open.Strain the stock through a cheesecloth and reserve.In an 8-quart saucepan, heat the oil.Add the onion and garlic and saut over medium heat until soft, but not browned.Add tomatoes, tomato paste, and remaining 2 cups of wine, pepper, herbs, and clam stock.Partially cover and simmer for 20 minutes.Add the fish, scallops, shrimp, crab, and crab butter.Simmer for approximately 5 minutes or until all seafood is cooked; do not stir or the fish will break apart.Add the clams and heat for a scant 1 minute.Sprinkle with parsley and serve immediately from the pot.','557.3','https://img.spoonacular.com/recipes/659237-556x370.jpg'),(659742,'Serbian Raznjici - Kebabs With Pork, Bacon, Onion and Sweet Pepper','[\"300 grams pork meat\", \"1/2 small red pepper\", \"1/2 small green pepper\", \"1/2 small onion\", \"100 grams cured bacon\", \"2 pinch ground black pepper\", \"3 pinch salt\", \"2 tablespoons oil, olive or plain salad oil\"]','Cut the meat, peppers, onions and bacon in to bite size squares.\nArrange cut ingredients on wooden stick.\nPlace oil in a grill pan and pan roast for about 10-15 minutes until golden brown. In the process of roasting, add salt and pepper.','519.02','https://img.spoonacular.com/recipes/659742-556x370.jpg'),(662375,'Surf and Turf Kababs','[\"1/2 cup balsamic vinegar\", \"red & yellow bell pepper, cut into large chunks\", \"1/2 cup brown sugar\", \"24 button mushrooms, whole\", \"1 inch piece fresh ginger, peeled & minced\", \"1 teaspoon fresh thyme, minced\", \"4 cloves garlic, minced\", \"4 green onions, finely chopped\", \"green onions\", \"1 teaspoon pepper\", \"24 cubes fresh or canned pineapple\", \"1/2 cup pineapple juice (reserved from can)\", \"2 pounds ribeye steaks, trimmed of fat & cut into 24 chunks\", \"24 large shrimp, peeled, deveined & tail on\", \"1 cup soy sauce\"]','Place cut meat &amp; vegetables in Ziploc bag and pour half of marinade over them.  Seal tight and roll bag in hands to thoroughly coat ingredients.  Place bag in refrigerator and let marinate at least 4 to 6 hours or overnight.When ready to grill, pour off excess marinade and string meat and veggies alternately on skewers.Heat grill to medium-high heat and grill kabobs directly over coals or gas flame.  Grill for about 6 to 8 minutes per side or until desired doneness.  During the last 5 minutes of cooking, baste kabobs with glaze and close grill and let caramelize.Marinade &amp; GlazeCombine marinade and pour off half into a small saucepan.  Pour the remaining half over meet and vegetables in Ziploc bag.For glaze:  Cook glaze over medium heat, stirring occasionally.  Reduce mixture by 1/3 to 1/2 or until glaze coats the back of a spoon.','749.38','https://img.spoonacular.com/recipes/662375-556x370.jpg'),(664748,'Veggie Meatloaf','[\"1/2 cup finely chopped onion\", \"2 cloves garlic\", \"2 tablespoons butter\", \"2 pounds ground chuck\", \"2 eggs\", \"1/4 cup cream\", \"2 tablespoons Worcestershire sauce\", \"1 1/2 teaspoons salt\", \"1/2 teaspoon freshly ground black pepper\", \"1 tablespoon teaspoon dried thyme, or 1 fresh, finely chopped\", \"1 cup shredded carrots or yellow squash or zucchini, or a comb\"]','Preheat the oven to 350 F.\nMelt the butter in a small skillet over medium-low heat; add the onions and cook, stirring frequently, until they are soft and translucent but not brown, about 7  8 minutes.  Add the garlic and cook, stirring frequently, for another minute or two.  Remove from heat and set aside.\nPlace the remaining ingredients to a large mixing bowl; add the onion/garlic mixture.  Gently but thoroughly mix with your hands, then transfer to an 8x8 baking dish and form into a loaf shape.\nBake for 1 hour, then test to see if the center is done.  If it is still pink, cover with foil and bake for another 10 to 15 minutes.  Allow the meatloaf to rest for about 5 minutes before serving.','488.65','https://img.spoonacular.com/recipes/664748-556x370.jpg'),(665378,'Winter Fattoush Salad','[\"1 teaspoon agave nectar\", \"1/4 cup feta cheese (optional)\", \"\\u00bd cup flat leaf parsley leaves (or a mix of parsley and mint)\", \"2 cloves garlic, minced\", \"\\u00bd teaspoon ground sumac\", \"1 teaspoon kosher salt\", \"4 fresh Lacinato kale leaves\", \"2 tablespoons lemon juice\", \"1\\u00bd cups cooked lentils (many markets carry vacuum-packed, precooked lentils, or boil 1 cup dried brown lentils in 2 cups salted water until tender, then drain)\", \"3 tablespoons olive oil\", \"1 small onion, coarsely chopped\", \"1 tablespoon minced parsley\", \"1 large organic English or Persian cucumber with skin (about 1 cup shredded)\", \"2 large pita breads\", \"1 small bunch red radishes or other varietals such as watermelon or daikon (about \\u00bd cup, shredded)\", \"Salt and freshly ground black pepper to taste\", \"1 small head savoy cabbage (about 2 heaping cups, shredded)\", \"1 tablespoon za\'atar\"]','Toast the pita: Preheat the oven to 350F. Whisk the oil, zaatar and salt in a small bowl.  Lay the pita bread on a baking sheet and brush both sides with the oil. Bake until crisp, 5 to 7 minutes. When cool enough to handle, tear pitas into bite-size pieces. There should be about 2 cups.Make the lentils: Saute the onions and oil in a small skillet until onions soften and begin to brown. Add the lentils and stir to blend. Stir in the garlic and parsley and remove from heat. Season with salt and pepper.Cut away the thickest part of the kale and cabbage ribs and discard, then roll the leaves into bundles and shred. Trim the cucumber ends, then cut lengthwise into -inch slices. Stack the slices and cut crosswise into shreds. Repeat with the radishes. Tear whole leaves from parsley and/or mint.Make the dressing: Whisk the dressing ingredients in a bowl until fully combined. You can also use a handheld blender.Compose the salad: Toss the salad ingredients in a large bowl. Add the lentils and pita crisps. Drizzle with the dressing and toss again. Mound the salad on a serving platter. Top with feta cheese and sprinkle with sumac.','345.17','https://img.spoonacular.com/recipes/665378-556x370.jpg'),(665496,'Yakitori Glaze','[\"1 teaspoon Grated fresh ginger\", \"cup Mirin (sweet rice wine)\", \"cup Sake\", \"cup Japanese soy sauce\", \"cup Sugar\", \"1 ounce Tamari\"]','In a saucepan, combine soy sauce, mirin, sake, and brown sugar. Optionally add chicken skin for extra richness. Bring to a boil over medium heat, then lower the heat and simmer for about 10-15 minutes until slightly thickened. Remove chicken skin if used and strain the sauce for a smooth consistency. Let the glaze cool before using to baste grilled chicken skewers during cooking. Store any leftover glaze in the refrigerator.','392.75','https://img.spoonacular.com/recipes/665496-556x370.jpg'),(665517,'pakistani paya','[\"4 pieces of lamb or goat trotters\", \"1 onion, chopped\", \"1 tablespoon ginger paste\", \"1 tablespoon garlic paste\", \"1 teaspoon turmeric powder\", \"1 teaspoon red chili powder\", \"1 teaspoon coriander powder\", \"1 teaspoon cumin powder\", \"Salt to taste\", \"Water\", \"Fresh cilantro leaves for garnish\", \"Ginger slices for garnish\", \"Green chilies for garnish\"]','1. Clean the trotters thoroughly and boil them in water for 5 minutes. Discard the water.\n2. In a pressure cooker, add the trotters, onion, ginger paste, garlic paste, turmeric powder, red chili powder, coriander powder, cumin powder, salt, and enough water to cover the trotters.\n3. Pressure cook for about 1-2 hours until the trotters are tender.\n4. Once cooked, garnish with fresh cilantro, ginger slices, and green chilies.\n5. Serve hot with naan or rice.','350','data:image/jpeg;base64,'),(665518,'Takoyaki','[\"1 cup all-purpose flour\", \"1 1/2 cups dashi (Japanese soup stock)\", \"2 eggs\", \"1/2 lb cooked octopus, chopped\", \"1/4 cup chopped green onions\", \"1/4 cup pickled red ginger\", \"1/4 cup tenkasu (tempura scraps)\", \"Takoyaki sauce\", \"Japanese mayonnaise\", \"Aonori (dried green seaweed)\", \"Katsuobushi (dried bonito flakes)\"]','1. Mix flour and dashi in a bowl until smooth. Add eggs and mix well. 2. Heat takoyaki pan and grease with oil. 3. Pour batter into the holes of the pan, add octopus, green onions, red ginger, and tenkasu. 4. Cook until edges are set, then use a skewer to rotate the takoyaki balls. 5. Keep rotating until fully cooked and crispy. 6. Serve with takoyaki sauce, mayonnaise, aonori, and katsuobushi.','250','data:image/jpeg;base64,'),(665519,'manto','[\"1 lb ground lamb or beef\", \"1 onion, finely chopped\", \"2 cloves of garlic, minced\", \"1 tsp ground cumin\", \"1 tsp ground coriander\", \"1/2 tsp ground cinnamon\", \"Salt and pepper to taste\", \"1 package of dumpling wrappers\", \"1 cup water\"]','1. In a large mixing bowl, combine the ground meat, onion, garlic, cumin, coriander, cinnamon, salt, and pepper. Mix well.\n2. Take a dumpling wrapper and place a spoonful of the meat mixture in the center. Fold the wrapper in half and seal the edges by pressing with a fork.\n3. Repeat with the remaining meat mixture and wrappers.\n4. In a large pot, bring water to a boil. Add the dumplings to the pot and cook for about 20 minutes, or until the meat is cooked through.\n5. Serve hot with your favorite dipping sauce.','450','data:image/jpeg;base64,'),(665520,'pakistsani chai','[\"2 cups water\", \"2 tbsp loose black tea leaves\", \"1 cup whole milk\", \"2-3 tbsp sugar\", \"1-2 slices of fresh ginger\", \"1-2 cardamom pods\", \"Pinch of cloves\", \"Pinch of cinnamon\"]','1. In a small pot, bring water to a boil. \n2. Add tea leaves, ginger, cardamom pods, cloves, and cinnamon. \n3. Let it simmer for 5-7 minutes. \n4. Add milk and sugar, and let it simmer for another 2-3 minutes. \n5. Strain the chai into a cup and enjoy hot.','90','data:image/jpeg;base64,'),(665521,'hot chai','[\"2 cups of water\", \"2 black tea bags\", \"1 cinnamon stick\", \"4 cloves\", \"4 cardamom pods\", \"1 inch piece of fresh ginger, peeled and sliced\", \"2 cups of milk\", \"4 tablespoons of sugar\"]','1. In a saucepan, bring water to a boil. Add the tea bags, cinnamon stick, cloves, cardamom pods, and ginger. Simmer for 5 minutes.\n2. Add milk and sugar, bring to a boil.\n3. Strain the chai into mugs and serve hot.','150','data:image/jpeg;base64,'),(665522,'sajji','[\"1 whole chicken, cleaned and slit\", \"1 cup yogurt\", \"2 tbsp ginger garlic paste\", \"1 tbsp red chili powder\", \"1 tbsp turmeric powder\", \"1 tbsp coriander powder\", \"1 tbsp cumin powder\", \"Salt to taste\", \"1 lemon, juiced\", \"1/4 cup vegetable oil\"]','1. In a bowl, mix yogurt, ginger garlic paste, red chili powder, turmeric powder, coriander powder, cumin powder, salt, lemon juice, and vegetable oil to make a marinade. \n2. Rub the marinade all over the chicken, making sure to get it into the slits. \n3. Marinate the chicken for at least 4 hours, or overnight for best results. \n4. Preheat the oven to 375°F (190°C). \n5. Place the marinated chicken on a baking tray and cook for about 45-60 minutes or until the chicken is cooked through and golden brown. \n6. Serve hot with naan or rice.','400','data:image/jpeg;base64,'),(665523,'shinwari karahi','[\"1 kg mutton or chicken, cut into pieces\", \"1/2 cup cooking oil\", \"1 large onion, thinly sliced\", \"2 tomatoes, chopped\", \"1 tbsp ginger garlic paste\", \"1 tsp turmeric powder\", \"1 tsp red chili powder\", \"1 tsp coriander powder\", \"1 tsp cumin powder\", \"1 tsp garam masala\", \"Salt to taste\", \"Fresh coriander leaves for garnish\"]','1. Heat oil in a karahi or deep pan. \n2. Add sliced onions and sauté until golden brown. \n3. Add ginger garlic paste and cook for a minute. \n4. Add the chopped tomatoes and cook until they are soft. \n5. Add the mutton or chicken pieces and mix well. \n6. Add turmeric powder, red chili powder, coriander powder, cumin powder, garam masala, and salt. Mix well. \n7. Cover and cook on low heat until the meat is tender. \n8. Garnish with fresh coriander leaves before serving.','450','data:image/jpeg;base64,'),(665524,'tom yum','[\"4 cups water\", \"2 stalks lemongrass, smashed\", \"3-4 slices galangal\", \"5 kaffir lime leaves\", \"6-8 bird\'s eye chilies, smashed\", \"200g shrimp, peeled and deveined\", \"200g mushrooms, sliced\", \"2 tomatoes, quartered\", \"2 tablespoons fish sauce\", \"2 tablespoons lime juice\", \"1 tablespoon sugar\", \"1 handful cilantro leaves\"]','1. In a pot, bring water to a boil and add lemongrass, galangal, kaffir lime leaves, and bird\'s eye chilies. Let simmer for 5-10 minutes.\n2. Add shrimp, mushrooms, and tomatoes. Cook until shrimp is pink and cooked through.\n3. Stir in fish sauce, lime juice, and sugar. Taste and adjust seasoning if necessary.\n4. Remove from heat and garnish with cilantro leaves before serving.','250','data:image/jpeg;base64,'),(665525,'tom yum','[\"2 stalks lemongrass\", \"5 kaffir lime leaves\", \"3-4 slices of galangal\", \"3-4 Thai bird\'s eye chilies\", \"200g shrimp\", \"200g mushrooms\", \"1 tomato\", \"2 shallots\", \"1/4 cup fish sauce\", \"1/4 cup lime juice\", \"1 tbsp sugar\", \"1/2 cup coconut milk\", \"4 cups water\"]','1. Bruise lemongrass, kaffir lime leaves, and galangal. \n2. Bring water to a boil and add lemongrass, kaffir lime leaves, galangal, and chilies. \n3. Add shrimp, mushrooms, tomato, and shallots. \n4. Season with fish sauce, lime juice, and sugar. \n5. Add coconut milk and simmer until flavors meld. \n6. Serve hot.','350','data:image/jpeg;base64,'),(665526,'fondue','[\"1 clove garlic\", \"1 cup dry white wine\", \"1 tbsp lemon juice\", \"2 cups shredded Swiss cheese\", \"2 cups shredded Gruyere cheese\", \"2 tbsp cornstarch\", \"1 tbsp cherry brandy (optional)\", \"1 French baguette, cut into cubes\"]','1. Rub the inside of a fondue pot with the garlic clove.\n2. Pour the wine and lemon juice into the pot and heat until simmering.\n3. In a bowl, toss the shredded cheeses with cornstarch.\n4. Gradually stir in the cheese mixture into the pot, stirring constantly until melted and smooth.\n5. Stir in the cherry brandy if using.\n6. Serve with cubes of French baguette for dipping.','650','data:image/jpeg;base64,'),(665527,'Peking duck','[\"1 whole duck\", \"1/4 cup honey\", \"1/4 cup soy sauce\", \"1/4 cup hoisin sauce\", \"2 tablespoons vinegar\", \"1 tablespoon Chinese five spice powder\", \"1 teaspoon garlic powder\", \"Salt and pepper to taste\", \"Thinly sliced cucumbers, scallions, and pancakes for serving\"]','1. Preheat oven to 350°F (175°C). 2. In a small bowl, mix together honey, soy sauce, hoisin sauce, vinegar, Chinese five spice powder, garlic powder, salt, and pepper. 3. Place duck on a rack in a roasting pan and brush both sides with the sauce. 4. Roast duck in the preheated oven for about 2 hours, basting every 30 minutes. 5. Remove duck from the oven and let it rest for 10 minutes before carving. 6. Serve the duck with the thin cucumbers, scallions, pancakes, and extra sauce on the side.','600','data:image/jpeg;base64,'),(665528,'Neapolitan pizza','[\"1 lb pizza dough\", \"1/2 cup tomato sauce\", \"1 cup shredded mozzarella cheese\", \"1/4 cup grated parmesan cheese\", \"Fresh basil leaves\", \"Olive oil\", \"Salt\", \"Pepper\"]','1. Preheat your oven to the highest temperature it can go. 2. Roll out the pizza dough on a floured surface into a circle. 3. Spread the tomato sauce evenly over the dough, leaving a small border around the edges. 4. Sprinkle the mozzarella and parmesan cheese over the sauce. 5. Tear the basil leaves and scatter them over the cheese. 6. Drizzle some olive oil over the top and season with salt and pepper. 7. Bake in the oven for 10-15 minutes or until the crust is golden brown and the cheese is bubbly. 8. Slice and serve hot.','800','data:image/jpeg;base64,'),(665529,' Peking duck','[\"1 whole duck\", \"1 tbsp honey\", \"1 tbsp soy sauce\", \"1 tbsp hoisin sauce\", \"1 tsp five-spice powder\", \"1 tsp salt\", \"2 cloves garlic, minced\", \"1 inch piece of ginger, minced\", \"1 green onion, chopped\", \"1 tbsp rice vinegar\", \"1 tbsp cornstarch\"]','1. Preheat the oven to 350°F. 2. Clean the duck and pat dry. 3. In a small bowl, mix together honey, soy sauce, hoisin sauce, five-spice powder, salt, garlic, ginger, green onion, rice vinegar, and cornstarch. 4. Rub the mixture all over the duck, making sure to coat it evenly. 5. Place the duck on a rack in a roasting pan. 6. Roast in the oven for 2-3 hours, until the skin is crispy and the meat is tender. 7. Serve hot with steamed pancakes, sliced cucumbers, and hoisin sauce.','350','data:image/jpeg;base64,'),(665530,'Arepas','[\"2 cups pre-cooked white corn flour (masarepa)\", \"2 1/2 cups warm water\", \"1 tsp salt\", \"1 cup shredded mozzarella cheese\", \"2 tbsp butter\"]','1. In a bowl, mix the white corn flour with the warm water and salt until a dough forms. \n2. Divide the dough into equal portions and shape them into rounds. \n3. Heat a skillet over medium heat and cook the arepas for about 5 minutes on each side, or until golden brown. \n4. Cut the arepas in half and fill them with shredded mozzarella cheese. \n5. Top with butter before serving.','250','https://encrypted-tbn3.gstatic.com/images?q=tbn:ANd9GcTHqO98M0_RVs2GLhds05R8Adi38eQJSDd2jXAkXbUQN5f_NUMaMr8E2uUNymQ0mIlcGUgrXgoo0vyAhWwPiPfgELPMZ1or2bDY4Fc0H1vy'),(665531,'pakistani nihari','[\"2 lbs beef shank\", \"1/2 cup ghee\", \"2 large onions, sliced\", \"1/4 cup wheat flour\", \"1 tbsp ginger garlic paste\", \"1 tsp turmeric\", \"1 tbsp red chili powder\", \"1 tbsp coriander powder\", \"1 tsp cumin powder\", \"1/2 tsp garam masala\", \"Salt to taste\", \"6 cups water\", \"Ginger slices, green chilies, and fresh coriander for garnish\"]','1. Heat ghee in a large pot and fry the onions until golden brown. \n2. Add the beef shank and ginger garlic paste, and cook until the meat is browned. \n3. Add wheat flour and spices, and cook for a few minutes. \n4. Pour in water, cover, and simmer on low heat for 4-5 hours or until the meat is tender. \n5. Garnish with ginger slices, green chilies, and fresh coriander before serving.','350','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750238963/recipes/pakistani%20nihari_image.jpg'),(665532,'zarda','[\"1 cup basmati rice\", \"1/2 cup sugar\", \"1/4 cup ghee\", \"1/4 cup mixed nuts (almonds, cashews, raisins)\", \"1/4 tsp saffron strands\", \"1/4 tsp cardamom powder\", \"1/4 tsp rose water\", \"4 cups water\"]','1. Wash the rice and soak in water for 30 minutes. \n2. In a large pot, bring 4 cups of water to a boil. \n3. Add the soaked rice and cook until almost done. Drain and set aside. \n4. In a separate pan, heat ghee and fry the mixed nuts until golden brown. \n5. Add sugar, saffron strands, and cardamom powder to the pan with the nuts. Stir well. \n6. Add the cooked rice to the pan and mix everything together. \n7. Cover and cook on low heat for 10-15 minutes. \n8. Add rose water and mix well. \n9. Serve hot or cold.','350','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750241236/recipes/zarda_image.jpg'),(665533,'Tamarind duck','[\"1 whole duck, about 4-5 lbs\", \"1 cup tamarind paste\", \"1/2 cup soy sauce\", \"1/4 cup honey\", \"4 cloves garlic, minced\", \"1 inch ginger, grated\", \"2 tbsp vegetable oil\", \"Salt and pepper to taste\", \"1/2 cup water\"]','1. Preheat the oven to 350°F. \n2. In a small bowl, mix together tamarind paste, soy sauce, honey, garlic, ginger, salt, and pepper. \n3. Rub the duck inside and out with the tamarind mixture. \n4. Place the duck in a roasting pan and add water to the bottom of the pan. \n5. Cover the duck with aluminum foil and roast for about 2 hours, basting occasionally with the pan juices. \n6. Remove the foil and increase the oven temperature to 450°F. Roast for another 30 minutes or until the duck is browned and crispy. \n7. Let the duck rest for 10 minutes before carving. \n8. Serve with steamed rice or vegetables.','350','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750241845/recipes/Tamarind%20duck_image.jpg'),(665534,'Halwa Puri','[\"1 cup semolina\", \"1/2 cup ghee\", \"1 cup sugar\", \"4 cups water\", \"1/4 cup chopped almonds\", \"1/4 cup chopped pistachios\", \"1/4 cup raisins\", \"1/4 tsp cardamom powder\"]','1. In a pan, heat ghee and add semolina. Roast until golden brown.\n2. In a separate pot, combine water and sugar to make a syrup.\n3. Slowly add the syrup to the roasted semolina while stirring continuously.\n4. Add almonds, pistachios, raisins, and cardamom powder.\n5. Cook until the mixture thickens and starts to leave the sides of the pan.\n6. Serve hot with puris.','350','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750242199/recipes/Halwa%20Puri_image.jpg'),(665535,'rasmalai','[\"1 liter full cream milk\", \"2 tablespoons lemon juice\", \"1/2 cup sugar\", \"1/4 teaspoon cardamom powder\", \"2 tablespoons chopped nuts (pistachios, almonds, etc.)\"]','1. Boil the milk in a heavy-bottomed pan. \n2. When it comes to a boil, add lemon juice and stir to curdle the milk. \n3. Remove from heat and strain the curdled milk through a muslin cloth. \n4. Rinse the chenna (curdled milk) under cold water to remove the lemon taste. \n5. Squeeze out excess water and knead the chenna until smooth. \n6. Form into small balls and flatten slightly. \n7. In a separate pan, bring water to a boil with sugar and cardamom powder. \n8. Add the chenna balls and simmer for 15-20 minutes. \n9. Let it cool, then refrigerate. \n10. Garnish with chopped nuts before serving.','250','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750242322/recipes/rasmalai_image.jpg'),(665536,'pakistani style rasmalai','[\"1 liter whole milk\", \"1/4 cup sugar\", \"1/4 cup water\", \"1/4 cup milk powder\", \"1/4 cup almonds, chopped\", \"1/4 cup pistachios, chopped\", \"1/4 teaspoon cardamom powder\", \"1 tablespoon rose water\", \"1 tablespoon lemon juice\", \"Saffron strands (optional)\"]','1. In a pan, bring the whole milk to a boil. Add lemon juice and stir well to curdle the milk. Drain the curdled milk through a muslin cloth to separate the chenna (paneer) from the whey. Rinse the chenna under cold water.\n2. In a separate pan, combine sugar and water and bring to a boil to make a sugar syrup. Add the chenna, milk powder, chopped almonds, pistachios, cardamom powder, rose water, and saffron strands to the sugar syrup. Cook for 10-15 minutes until the mixture thickens.\n3. Let the mixture cool, then shape it into small round balls and refrigerate for a few hours.\n4. Garnish with additional chopped nuts and serve chilled.','250','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750242386/recipes/pakistani%20style%20rasmalai_image.jpg'),(665537,'Vada pav','[\"2 medium potatoes, boiled and mashed\", \"1 cup gram flour (besan)\", \"1 tsp turmeric powder\", \"1 tsp red chili powder\", \"1 tsp cumin seeds\", \"1 tsp mustard seeds\", \"1 inch ginger, grated\", \"2-3 green chilies, chopped\", \"1/4 cup chopped coriander leaves\", \"Salt to taste\", \"Oil for frying\", \"6 pav (dinner rolls)\", \"Garlic chutney\", \"Green chutney\", \"Tamarind chutney\", \"Fried green chilies (optional)\", \"Fried green chilies (optional)\"]','1. In a bowl, mix together mashed potatoes, gram flour, turmeric powder, red chili powder, cumin seeds, mustard seeds, ginger, green chilies, coriander leaves, and salt. \n2. Divide the mixture into equal parts and shape them into round patties.\n3. Heat oil in a pan and fry the patties until golden brown and crispy.\n4. Slit the pav (dinner rolls), spread garlic chutney on one side and green chutney on the other.\n5. Place a vada (potato patty) between the pav.\n6. Serve hot with tamarind chutney and fried green chilies.','300','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750243740/recipes/Vada%20pav_image.jpg'),(665538,'Aloo gobi','[\"2 medium potatoes, peeled and diced\", \"1 small cauliflower, cut into florets\", \"1 onion, chopped\", \"2 tomatoes, chopped\", \"2 cloves of garlic, minced\", \"1 inch piece of ginger, grated\", \"1 tsp turmeric powder\", \"1 tsp cumin powder\", \"1 tsp coriander powder\", \"1/2 tsp red chili powder\", \"Salt to taste\", \"2 tbsp oil\", \"Fresh coriander leaves for garnish\"]','1. Heat oil in a pan and add the chopped onion, garlic, and ginger. Cook until onions are translucent.\n2. Add the tomatoes, turmeric powder, cumin powder, coriander powder, red chili powder, and salt. Cook until tomatoes are soft.\n3. Add the diced potatoes and cauliflower florets. Mix well to coat them with the spices.\n4. Cover and cook on low heat until the vegetables are tender, stirring occasionally.\n5. Garnish with fresh coriander leaves before serving.','250','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750244573/recipes/Aloo%20gobi_image.jpg'),(665539,'Balut','[\"8 fresh duck eggs\", \"Water\", \"Vinegar\", \"Salt\"]','1. Wash the duck eggs thoroughly. \n2. Boil a pot of water and add vinegar and salt. \n3. Carefully place the duck eggs in the boiling water. \n4. Boil for about 20-30 minutes. \n5. Remove from heat and let the eggs cool down. \n6. Peel the shell of the eggs and enjoy the balut.','188 calories','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750250366/recipes/Balut_image.jpg'),(665540,'Escamol','[\"1 cup escamol (ant larvae)\", \"1/4 onion, finely chopped\", \"2 cloves garlic, minced\", \"2 tablespoons olive oil\", \"Salt and pepper to taste\"]','1. Heat olive oil in a skillet over medium heat. Add the onion and garlic, and sauté until softened.\n2. Add the escamol to the skillet and cook until heated through.\n3. Season with salt and pepper to taste.\n4. Serve hot as a side dish or filling for tacos.','200','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750250513/recipes/Escamol_image.jpg'),(665541,'kimuchi','[\"1 Napa cabbage\", \"1/4 cup salt\", \"1/4 cup Korean red pepper flakes\", \"2 tablespoons minced garlic\", \"1 tablespoon minced ginger\", \"3 green onions, chopped\", \"1 small carrot, julienned\", \"1 tablespoon sugar\", \"1 tablespoon fish sauce\", \"1 tablespoon soy sauce\"]','1. Cut the Napa cabbage into quarters lengthwise, then chop into bite-sized pieces. Place in a large bowl and sprinkle salt over the cabbage, tossing to coat. Let sit for 1-2 hours.\n2. Rinse the cabbage thoroughly to remove excess salt. Squeeze out excess moisture.\n3. In a separate bowl, mix together Korean red pepper flakes, garlic, ginger, green onions, carrot, sugar, fish sauce, and soy sauce.\n4. Add the cabbage to the mixture and toss to coat evenly.\n5. Pack the kimchi into a clean jar, pressing down to remove air bubbles.\n6. Let the kimchi ferment at room temperature for 1-2 days, then refrigerate for up to a week before serving.','120','https://res.cloudinary.com/dkkocyj9d/image/upload/v1750252213/recipes/kimuchi_image.jpg'),(665542,'Chilghoza Biryani','[\"1 cup basmati rice\", \"1/2 cup chilghoza (pine nuts)\", \"1 onion, thinly sliced\", \"1 tomato, chopped\", \"1/2 cup yogurt\", \"1 tsp ginger garlic paste\", \"1 tsp cumin seeds\", \"1 tsp coriander powder\", \"1 tsp turmeric powder\", \"1 tsp red chili powder\", \"1 tsp garam masala\", \"2-3 green chilies, chopped\", \"2 tbsp chopped coriander leaves\", \"2 tbsp ghee\", \"Salt to taste\", \"Water\"]','1. Wash and soak the basmati rice for 30 minutes. Drain and set aside. \n2. In a pan, heat ghee and add cumin seeds. \n3. Add sliced onions and sauté until golden brown. \n4. Add ginger garlic paste, chopped tomatoes, and green chilies. Cook until tomatoes are soft. \n5. Add all the spices - coriander powder, turmeric powder, red chili powder, and salt. Mix well. \n6. Add yogurt and cook until the oil separates. \n7. Add drained rice and mix well. \n8. Add water (1.5 cups for 1 cup of rice), cover and cook until the rice is done. \n9. In a separate pan, dry roast the chilghoza until lightly golden. \n10. Sprinkle roasted chilghoza and garam masala over the cooked biryani. \n11. Garnish with chopped coriander leaves. \n12. Serve hot with raita or salad.','375','https://res.cloudinary.com/dkkocyj9d/image/upload/v1751802170/recipes/Chilghoza%20Biryani_image.jpg'),(665543,'Pista Qeema Pulao','[\"1 cup basmati rice\", \"200g minced meat (beef or lamb)\", \"1 onion, thinly sliced\", \"2 tablespoons ghee\", \"1/2 cup shelled pistachios\", \"1 teaspoon cumin seeds\", \"1 teaspoon red chili powder\", \"1 teaspoon turmeric powder\", \"1 teaspoon garam masala\", \"Salt to taste\", \"2 cups water\"]','1. Wash and soak the rice for 30 minutes. Drain and set aside. \n2. In a large pot, heat ghee and add cumin seeds. \n3. Add sliced onions and cook until golden brown. \n4. Add minced meat and cook until browned. \n5. Add red chili powder, turmeric powder, garam masala, and salt. Cook for 2 minutes. \n6. Add shelled pistachios and drained rice. Mix well. \n7. Add water and bring to a boil. \n8. Reduce heat, cover, and cook until rice is tender and water is absorbed. \n9. Fluff rice with a fork before serving.','450','https://res.cloudinary.com/dkkocyj9d/image/upload/v1751802578/recipes/Pista%20Qeema%20Pulao_image.jpg'),(665544,'bun kabab','[\"1 lb ground beef\", \"1 small onion, finely chopped\", \"1 tsp ginger paste\", \"1 tsp garlic paste\", \"1 tsp red chili powder\", \"1 tsp turmeric powder\", \"1 tsp cumin powder\", \"1 tsp coriander powder\", \"Salt to taste\", \"4 burger buns\", \"Sliced tomatoes, onions, and lettuce for garnish\", \"Ketchup and chutney for serving\"]','1. In a bowl, mix together ground beef, onion, ginger paste, garlic paste, red chili powder, turmeric powder, cumin powder, coriander powder, and salt.\n2. Shape the mixture into round patties.\n3. Heat a pan and cook the patties until browned on both sides.\n4. Toast the burger buns.\n5. Place the cooked patty on the bottom half of the bun.\n6. Top with sliced tomatoes, onions, and lettuce.\n7. Drizzle with ketchup and chutney.\n8. Cover with the top half of the bun.\n9. Serve hot with extra ketchup and chutney on the side.','450','https://res.cloudinary.com/dkkocyj9d/image/upload/v1751913609/recipes/bun%20kabab_image.jpg'),(1506697,'Air Fryer Copycat KFC Chicken','[\"8 chicken legs\", \"1/2 cup panko\", \"1/2 cup flour all purpose\", \"2 tsp black pepper\", \"1 tsp salt\", \"1/2 tsp white pepper\", \"1/2 tsp cayenne pepper\", \"1/2 tsp oregano\", \"1 1/2 cups buttermilk\"]','Instructions\nAdd chicken legs to the buttermilk and allow to soak for at least 30 minutes.\nCombine panko, flour, and seasonings to a bowl. Mix well.\nRemove chicken from the buttermilk and place in a separate bowl.\nDip the chicken into the flour mixture, into the buttermilk, and back into the flour mixture.\nLay chicken legs on a sheet as you coat them.\nPlace a liner into the air fryer to help keep the chicken from sticking.\nPreheat the air fryer to 390 degrees.\nSpray both sides of the chicken with olive oil and then place in the air fryer once it has preheated..\nCook the chicken legs for 10 minutes, then flip and spray with oil again before cooking for the remaining 10 minutes. Make sure the temperature of the chicken has reached 160 degrees Fahrenheit before removing it from the Air Fryer.\nServe warm!','698.36','https://img.spoonacular.com/recipes/1506697-556x370.jpg'),(1506698,'bhat','[\"2 cups rice\", \"4 cups water\", \"Salt to taste\"]','1. Rinse the rice thoroughly in cold water. 2. In a large pot, bring the water to a boil. 3. Add the rice and salt, reduce heat to low, cover, and simmer for 15-20 minutes. 4. Remove from heat and let it sit, covered, for another 5 minutes. 5. Fluff with a fork before serving.','218','https://res.cloudinary.com/dkkocyj9d/image/upload/v1756796692/recipes/bhat_image.jpg'),(1506699,'nohari','[\"1 cup rice\", \"1 onion, chopped\", \"2 cloves garlic, minced\", \"1 tsp turmeric\", \"1 tsp cumin\", \"1 tsp coriander\", \"1 tsp paprika\", \"2 cups vegetable broth\", \"1 cup frozen peas\", \"1/2 cup cashews, chopped\", \"Salt and pepper to taste\"]','1. In a large skillet, sauté the onion and garlic until translucent. Add the rice and spices, stirring to coat the rice. 2. Pour in the vegetable broth and bring to a boil. Reduce heat, cover, and simmer for 15-20 minutes. 3. Stir in the peas and cashews, cover, and cook for an additional 5 minutes. Season with salt and pepper to taste. 4. Remove from heat and let sit for a few minutes before fluffing with a fork. Serve hot.','350','https://res.cloudinary.com/dkkocyj9d/image/upload/v1758796664/recipes/nohari_image.png'),(1506700,'palao','[\"2 cups basmati rice\", \"1 lb boneless chicken, cut into pieces\", \"1 onion, sliced\", \"1 tomato, diced\", \"1/2 cup plain yogurt\", \"2 cloves garlic, minced\", \"1 inch ginger, grated\", \"1 tsp cumin seeds\", \"1 tsp coriander powder\", \"1 tsp turmeric powder\", \"1 tsp red chili powder\", \"1/2 tsp garam masala\", \"4 cups water\", \"Salt to taste\", \"2 tbsp oil\", \"Fresh cilantro leaves for garnish\"]','1. Rinse the basmati rice in cold water until the water runs clear. Soak the rice in cold water for 30 minutes. 2. In a large pot, heat the oil over medium heat. Add the cumin seeds and sauté until they start to splutter. Add the sliced onion and cook until golden brown. 3. Add the minced garlic and grated ginger, cook for another minute. Add the diced tomato, coriander powder, turmeric powder, red chili powder, and salt. Cook until the tomatoes are soft. 4. Add the boneless chicken pieces and cook until they are no longer pink. 5. Stir in the plain yogurt and garam masala. Add the soaked rice and water, stir well. Bring to a boil, then reduce heat to low, cover and cook for 20 minutes or until the rice is cooked through and the water is absorbed. 6. Fluff the rice with a fork and garnish with fresh cilantro leaves before serving.','550','https://res.cloudinary.com/dkkocyj9d/image/upload/v1758796750/recipes/palao_image.jpg'),(1506701,'mac and cheez','[\"2 cups elbow macaroni\", \"2 cups shredded cheddar cheese\", \"1/2 cup butter\", \"1/2 cup all-purpose flour\", \"2 cups milk\", \"1/2 teaspoon salt\", \"1/2 teaspoon pepper\"]','1. Cook macaroni according to package instructions. 2. In a separate saucepan, melt butter over medium heat. 3. Stir in flour and cook for 1-2 minutes. 4. Gradually whisk in milk until smooth. 5. Add salt and pepper. 6. Bring mixture to a simmer and cook until thickened. 7. Stir in shredded cheese until melted. 8. Combine cheese sauce with cooked macaroni. 9. Serve hot.','450','https://res.cloudinary.com/dkkocyj9d/image/upload/v1760598437/recipes/mac%20and%20cheez_image.png');
